import type { Plugin } from "vite";
import mime from "mime-types";

interface ImageAssetPluginOptions {
  scope: string;
}

function isImageAsset(fileName: string): boolean {
  const mimeType = mime.lookup(fileName);
  return mimeType !== false && mimeType.startsWith("image/");
}

export function servicenowImageAssetPlugin(
  options: ImageAssetPluginOptions,
): Plugin {
  const { scope } = options;
  return {
    name: "servicenow-image-asset",
    enforce: "post",
    config(config) {
      config.experimental ??= {};
      const existingRenderBuiltUrl = config.experimental.renderBuiltUrl;
      config.experimental.renderBuiltUrl = (filename, info) => {
        if (isImageAsset(filename)) {
          return `/${scope}/${filename}`;
        }
        if (existingRenderBuiltUrl) {
          return existingRenderBuiltUrl(filename, info);
        }
        return { relative: true };
      };
    },
  };
}
